const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "mysql",
  "inlineSchema": "// Pointelio — schéma Prisma (MySQL)\n// Multi-tenant : chaque table métier porte entrepriseId, à contrôler sur chaque requête.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n}\n\n// ───────────── Enums ─────────────\n\nenum Role {\n  SUPER_ADMIN\n  SUPPORT\n  ADMIN_CLIENT\n  RESPONSABLE_RH\n  MANAGER\n  SURVEILLANT\n  EMPLOYE\n}\n\nenum StatutCompte {\n  INVITE\n  ACTIF\n  SUSPENDU\n  DESACTIVE\n}\n\nenum StatutEntreprise {\n  ESSAI\n  ACTIF\n  PAIEMENT_EN_ATTENTE\n  EN_RETARD\n  SUSPENDU\n  RESILIE\n}\n\nenum TypePointage {\n  ARRIVEE\n  DEPART\n}\n\nenum MethodePointage {\n  QR_GPS\n  SURVEILLANT\n}\n\n// VALIDE : dans le rayon / A_VERIFIER : zone grise ou précision faible / HORS_ZONE : au-delà du rayon\nenum StatutValidation {\n  VALIDE\n  A_VERIFIER\n  HORS_ZONE\n}\n\nenum TypeDemande {\n  CONGE_ANNUEL\n  MALADIE\n  AUTORISATION\n  RECUPERATION\n  AUTRE\n}\n\nenum StatutDemande {\n  EN_ATTENTE\n  APPROUVEE\n  REFUSEE\n  ANNULEE\n}\n\nenum StatutFacture {\n  BROUILLON\n  EMISE\n  PAYEE\n  EN_RETARD\n  ANNULEE\n}\n\n// ───────────── Offres et entreprises ─────────────\n\nmodel Pack {\n  id          Int      @id @default(autoincrement())\n  code        String   @unique // STARTER, BUSINESS, BUSINESS_PLUS, ENTREPRISE\n  nom         String\n  prixMensuel Int // FCFA, modifiable depuis l'admin\n  description String?\n  maxEmployes Int? // null = illimité\n  maxSites    Int? // null = illimité\n  essaiJours  Int      @default(0)\n  // Modules activés, ex : [\"QR\",\"GPS\",\"CONGES\",\"HORAIRES_MULTIPLES\",\"MULTI_SITES\",\"RAPPORTS_AVANCES\",\"ROLES_AVANCES\",\"SURVEILLANT\"]\n  // Tout est modifiable depuis le backoffice (CRUD des packs), sans toucher au code.\n  modules     Json\n  ordre       Int      @default(0)\n  actif       Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  entreprises Entreprise[]\n}\n\nmodel Entreprise {\n  id                  Int              @id @default(autoincrement())\n  raisonSociale       String\n  nomCommercial       String?\n  secteur             String?\n  pays                String           @default(\"CI\")\n  ville               String?\n  adresse             String?\n  identifiantLegal    String?\n  contactNom          String?\n  contactFonction     String?\n  contactEmail        String?\n  contactTel          String?\n  fuseauHoraire       String           @default(\"Africa/Abidjan\")\n  statut              StatutEntreprise @default(ESSAI)\n  packId              Int\n  dateDemarrage       DateTime?\n  dateEcheance        DateTime?\n  profilComplete      Boolean          @default(false)\n  // Surcharges optionnelles (offre sur mesure) : si renseignées, elles priment sur le pack\n  maxSitesOverride    Int?\n  maxEmployesOverride Int?\n  modulesOverride     Json?\n  notesInternes       String?          @db.Text // invisibles du client\n  createdAt           DateTime         @default(now())\n  updatedAt           DateTime         @updatedAt\n\n  pack         Pack          @relation(fields: [packId], references: [id])\n  utilisateurs Utilisateur[]\n  sites        Site[]\n  pointages    Pointage[]\n  horaires     Horaire[]\n  demandes     Demande[]\n  factures     Facture[]\n  invitations  Invitation[]\n  audits       AuditLog[]\n\n  @@index([statut])\n  @@index([packId])\n}\n\n// ───────────── Utilisateurs ─────────────\n\nmodel Utilisateur {\n  id                Int          @id @default(autoincrement())\n  entrepriseId      Int? // null pour SUPER_ADMIN / SUPPORT\n  siteId            Int? // site de rattachement (employé, surveillant)\n  horaireId         Int?\n  matricule         String?\n  nom               String\n  prenom            String\n  email             String?      @unique\n  telephone         String?      @unique // format international normalisé (+225...), connexion possible par numéro\n  passwordHash      String?\n  role              Role\n  statut            StatutCompte @default(INVITE)\n  poste             String?\n  // Salaire d'une journée travaillée (FCFA). Validé si arrivée + départ le même jour.\n  salaireJournalier Int?\n  dateEmbauche      DateTime?\n  photoUrl          String?\n  mfaActif          Boolean      @default(false)\n  derniereConnexion DateTime?\n  createdAt         DateTime     @default(now())\n  updatedAt         DateTime     @updatedAt\n\n  entreprise Entreprise? @relation(fields: [entrepriseId], references: [id])\n  site       Site?       @relation(\"SiteEmployes\", fields: [siteId], references: [id])\n  horaire    Horaire?    @relation(fields: [horaireId], references: [id])\n\n  pointages          Pointage[]           @relation(\"PointageEmploye\")\n  pointagesEffectues Pointage[]           @relation(\"PointagePar\")\n  corrections        PointageCorrection[]\n  demandes           Demande[]            @relation(\"DemandeEmploye\")\n  demandesTraitees   Demande[]            @relation(\"DemandeDecideur\")\n  refreshTokens      RefreshToken[]\n  notifications      Notification[]\n  audits             AuditLog[]\n\n  @@unique([entrepriseId, matricule])\n  @@index([entrepriseId, role])\n  @@index([siteId])\n}\n\nmodel Invitation {\n  id           Int       @id @default(autoincrement())\n  entrepriseId Int\n  email        String\n  role         Role\n  tokenHash    String    @unique\n  expireAt     DateTime\n  utiliseeAt   DateTime?\n  createdAt    DateTime  @default(now())\n\n  entreprise Entreprise @relation(fields: [entrepriseId], references: [id])\n\n  @@index([entrepriseId])\n}\n\nmodel RefreshToken {\n  id            Int       @id @default(autoincrement())\n  utilisateurId Int\n  tokenHash     String    @unique\n  appareil      String?\n  expireAt      DateTime\n  revoqueAt     DateTime?\n  createdAt     DateTime  @default(now())\n\n  utilisateur Utilisateur @relation(fields: [utilisateurId], references: [id], onDelete: Cascade)\n\n  @@index([utilisateurId])\n}\n\n// ───────────── Sites et horaires ─────────────\n\nmodel Site {\n  id            Int      @id @default(autoincrement())\n  entrepriseId  Int\n  nom           String\n  adresse       String?\n  latitude      Decimal  @db.Decimal(10, 7)\n  longitude     Decimal  @db.Decimal(10, 7)\n  rayonM        Int      @default(30) // paramétrable par site\n  precisionMaxM Int      @default(50) // au-delà : le mobile demande de réessayer\n  toleranceMin  Int? // facultatif : minutes de retard acceptées ; null = aucune tolérance extra\n  // Heures par jour ouvré, ex. [{\"jour\":1,\"heureDebut\":\"08:00\",\"heureFin\":\"17:00\"}]\n  // jour : 1 = lundi … 7 = dimanche.\n  horairesJours Json\n  qrToken       String   @unique // QR statique, jeton opaque, régénérable\n  actif         Boolean  @default(true)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  entreprise Entreprise    @relation(fields: [entrepriseId], references: [id])\n  employes   Utilisateur[] @relation(\"SiteEmployes\")\n  pointages  Pointage[]\n\n  @@index([entrepriseId])\n}\n\nmodel Horaire {\n  id           Int      @id @default(autoincrement())\n  entrepriseId Int\n  nom          String\n  heureDebut   String // \"08:00\"\n  heureFin     String // \"17:00\"\n  toleranceMin Int      @default(15)\n  joursTravail Json // [1,2,3,4,5]\n  createdAt    DateTime @default(now())\n\n  entreprise   Entreprise    @relation(fields: [entrepriseId], references: [id])\n  utilisateurs Utilisateur[]\n\n  @@index([entrepriseId])\n}\n\n// ───────────── Pointages ─────────────\n\nmodel Pointage {\n  id               BigInt           @id @default(autoincrement())\n  entrepriseId     Int\n  employeId        Int\n  siteId           Int\n  pointeParId      Int? // surveillant si methode = SURVEILLANT\n  type             TypePointage\n  methode          MethodePointage\n  latitude         Decimal?         @db.Decimal(10, 7)\n  longitude        Decimal?         @db.Decimal(10, 7)\n  precisionM       Float?\n  distanceM        Float?\n  statutValidation StatutValidation\n  motifStatut      String? // ex : \"distance 42 m, précision 18 m\"\n  mockDetecte      Boolean          @default(false)\n  requestId        String           @unique // idempotence (double appui)\n  heureServeur     DateTime         @default(now())\n  createdAt        DateTime         @default(now())\n\n  entreprise  Entreprise           @relation(fields: [entrepriseId], references: [id])\n  employe     Utilisateur          @relation(\"PointageEmploye\", fields: [employeId], references: [id])\n  pointePar   Utilisateur?         @relation(\"PointagePar\", fields: [pointeParId], references: [id])\n  site        Site                 @relation(fields: [siteId], references: [id])\n  corrections PointageCorrection[]\n\n  @@index([entrepriseId, heureServeur])\n  @@index([employeId, heureServeur])\n  @@index([siteId, heureServeur])\n  @@index([statutValidation])\n}\n\n// La valeur d'origine du pointage n'est jamais écrasée : on trace avant/après.\nmodel PointageCorrection {\n  id         Int      @id @default(autoincrement())\n  pointageId BigInt\n  auteurId   Int\n  motif      String\n  avant      Json\n  apres      Json\n  createdAt  DateTime @default(now())\n\n  pointage Pointage    @relation(fields: [pointageId], references: [id])\n  auteur   Utilisateur @relation(fields: [auteurId], references: [id])\n\n  @@index([pointageId])\n}\n\n// ───────────── Absences et congés ─────────────\n\nmodel Demande {\n  id              Int           @id @default(autoincrement())\n  entrepriseId    Int\n  employeId       Int\n  type            TypeDemande\n  dateDebut       DateTime      @db.Date\n  dateFin         DateTime      @db.Date\n  nbJours         Float?\n  commentaire     String?       @db.Text\n  justificatifUrl String?\n  statut          StatutDemande @default(EN_ATTENTE)\n  decideurId      Int?\n  decisionMotif   String?\n  decideAt        DateTime?\n  createdAt       DateTime      @default(now())\n\n  entreprise Entreprise   @relation(fields: [entrepriseId], references: [id])\n  employe    Utilisateur  @relation(\"DemandeEmploye\", fields: [employeId], references: [id])\n  decideur   Utilisateur? @relation(\"DemandeDecideur\", fields: [decideurId], references: [id])\n\n  @@index([entrepriseId, statut])\n  @@index([employeId])\n}\n\n// ───────────── Facturation ─────────────\n\nmodel Facture {\n  id           Int           @id @default(autoincrement())\n  entrepriseId Int\n  numero       String        @unique\n  periodeDebut DateTime      @db.Date\n  periodeFin   DateTime      @db.Date\n  lignes       Json\n  montantHT    Int\n  taxes        Int           @default(0)\n  montantTTC   Int\n  echeance     DateTime      @db.Date\n  statut       StatutFacture @default(EMISE)\n  createdAt    DateTime      @default(now())\n\n  entreprise Entreprise @relation(fields: [entrepriseId], references: [id])\n  paiements  Paiement[]\n\n  @@index([entrepriseId, statut])\n}\n\nmodel Paiement {\n  id        Int      @id @default(autoincrement())\n  factureId Int\n  montant   Int\n  moyen     String // WAVE, ORANGE_MONEY, VIREMENT, ESPECES...\n  reference String?\n  recuUrl   String?\n  payeAt    DateTime\n  createdAt DateTime @default(now())\n\n  facture Facture @relation(fields: [factureId], references: [id])\n\n  @@index([factureId])\n}\n\n// ───────────── Notifications et audit ─────────────\n\nmodel Notification {\n  id            Int       @id @default(autoincrement())\n  utilisateurId Int\n  titre         String\n  message       String    @db.Text\n  type          String\n  luAt          DateTime?\n  createdAt     DateTime  @default(now())\n\n  utilisateur Utilisateur @relation(fields: [utilisateurId], references: [id], onDelete: Cascade)\n\n  @@index([utilisateurId, luAt])\n}\n\nmodel AuditLog {\n  id           BigInt   @id @default(autoincrement())\n  entrepriseId Int?\n  acteurId     Int?\n  action       String // ex : POINTAGE_CORRIGE, ROLE_MODIFIE, EXPORT, SUSPENSION\n  objet        String?\n  objetId      String?\n  details      Json?\n  ip           String?\n  resultat     String   @default(\"OK\")\n  createdAt    DateTime @default(now())\n\n  entreprise Entreprise?  @relation(fields: [entrepriseId], references: [id])\n  acteur     Utilisateur? @relation(fields: [acteurId], references: [id])\n\n  @@index([entrepriseId, createdAt])\n  @@index([acteurId])\n}\n"
}

